/**
 * The base ActionContext for the GraphDisplay instances.
 */
public class GraphActionContext : DefaultActionContext {
	private AttributedGraph graph;
	private Set<AttributedVertex> selectedVertices;
	private AttributedVertex focusedVertex;

	public GraphActionContext(ComponentProvider componentProvider,
			AttributedGraph graph, Set<AttributedVertex> selectedVertices,
			AttributedVertex locatedVertex) : base(componentProvider)
    {
		this.graph = graph;
		this.selectedVertices = selectedVertices;
		this.focusedVertex = locatedVertex;
	}

	/**
	 * Returns the graph
	 * @return the graph
	 */
